pub struct StandardFieldDefinition {
    pub universal_identifier: &'static str,
    pub name: &'static str,
    pub label: &'static str,
    pub field_type: &'static str,
    pub description: Option<&'static str>,
    pub icon: Option<&'static str>,
    pub is_active: bool,
    pub is_system: bool,
    pub is_nullable: bool,
    pub is_audit_logged: bool,
    pub is_ui_editable: bool,
    pub is_label_synced_with_name: bool,
    pub is_system_side_effect: bool,
    pub default_value_json: Option<&'static str>,
    pub options_json: Option<&'static str>,
    pub settings_json: Option<&'static str>,
    pub overrides_json: Option<&'static str>,
    pub morph_id: Option<&'static str>,
    pub relation_target_field_universal_identifier: Option<&'static str>,
    pub relation_target_object_universal_identifier: Option<&'static str>,
}

pub struct StandardObjectDefinition {
    pub universal_identifier: &'static str,
    pub name_singular: &'static str,
    pub name_plural: &'static str,
    pub label_singular: &'static str,
    pub label_plural: &'static str,
    pub description: Option<&'static str>,
    pub icon: Option<&'static str>,
    pub color: Option<&'static str>,
    pub target_table_name: &'static str,
    pub is_system: bool,
    pub is_active: bool,
    pub is_searchable: bool,
    pub is_audit_logged: bool,
    pub is_label_synced_with_name: bool,
    pub open_record_in: Option<&'static str>,
    pub duplicate_criteria_json: Option<&'static str>,
    pub overrides_json: Option<&'static str>,
    pub shortcut: Option<&'static str>,
    pub label_identifier_field_universal_identifier: Option<&'static str>,
    pub image_identifier_field_universal_identifier: Option<&'static str>,
    pub fields: &'static [StandardFieldDefinition],
    pub column_plan: &'static [&'static str],
}

pub struct StandardFieldOptionDefinition {
    pub universal_identifier: &'static str,
    pub field_universal_identifier: &'static str,
    pub value: &'static str,
    pub label: &'static str,
    pub color: Option<&'static str>,
    pub position: f64,
}

pub struct StandardIndexDefinition {
    pub universal_identifier: &'static str,
    pub name: &'static str,
    pub object_universal_identifier: &'static str,
    pub is_unique: bool,
    pub index_where_clause: Option<&'static str>,
    pub index_type: &'static str,
    pub columns: &'static [StandardIndexColumnDefinition],
}

pub struct StandardIndexColumnDefinition {
    pub order: i32,
    pub field_universal_identifier: &'static str,
    pub sub_field_name: Option<&'static str>,
}

pub struct StandardSearchFieldDefinition {
    pub universal_identifier: &'static str,
    pub object_universal_identifier: &'static str,
    pub field_universal_identifier: &'static str,
    pub ts_vector_field_universal_identifier: &'static str,
    pub position: f64,
}

